import{_ as t,o,c as i,a5 as n}from"./chunks/framework.Cct9zD0Q.js";const a="/RBQ/nightly/images/operation/iptime-home.en.png",r="/RBQ/nightly/images/operation/iptime-wisp-mode.en.png",s="/RBQ/nightly/images/operation/iptime-wisp-scan.en.png",c="/RBQ/nightly/images/operation/iptime-wisp-form.en.png",h="/RBQ/nightly/images/operation/iptime-dynamic-ip.en.png",f=JSON.parse('{"title":"Connecting the Robot to the Internet","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/operation/robot-internet.md","filePath":"manual/operation/robot-internet.md","lastUpdated":1795599730000}'),d={name:"manual/operation/robot-internet.md"};function l(p,e,m,g,u,b){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="connecting-the-robot-to-the-internet" tabindex="-1">Connecting the Robot to the Internet <a class="header-anchor" href="#connecting-the-robot-to-the-internet" aria-label="Permalink to &quot;Connecting the Robot to the Internet&quot;">​</a></h1><p>Remote check and remote app connection need the robot itself on the internet. The robot&#39;s router joins the site Wi-Fi as a client (wireless WAN, also called WISP) and shares that connection with the robot. A robot with its own USIM is already on the internet and can skip this page.</p><h2 id="before" tabindex="-1">Before you start <a class="header-anchor" href="#before" aria-label="Permalink to &quot;Before you start {#before}&quot;">​</a></h2><ul><li>The name and password of a site Wi-Fi network that reaches the internet.</li><li>A phone, tablet or PC on the robot&#39;s Wi-Fi (<code>RBQ_{XX}</code>).</li><li>The router admin password. Ask support if you do not have it.</li></ul><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>A network that needs a web sign-in page or device (MAC) registration does not work here. Use a phone hotspot instead — set it up the same way, picking the hotspot as the site Wi-Fi.</p></div></div><h2 id="open" tabindex="-1">Step 1: Open the router settings <a class="header-anchor" href="#open" aria-label="Permalink to &quot;Step 1: Open the router settings {#open}&quot;">​</a></h2><ol><li>On a device on the robot&#39;s Wi-Fi, open <code>http://192.168.0.1</code> in a browser.</li><li>Enter the login name and password and sign in.</li><li>On the next screen, press <code>Setup</code>. Do not choose <code>Wizard</code>.</li></ol><p>The router screens are in Korean or English. The globe button at the bottom of the menu switches between them; this page shows the English screens.</p><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+a+'" alt="ipTIME start screen after sign-in" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Choose Setup ]</figcaption></figure><h2 id="wisp" tabindex="-1">Step 2: Turn on wireless WAN <a class="header-anchor" href="#wisp" aria-label="Permalink to &quot;Step 2: Turn on wireless WAN {#wisp}&quot;">​</a></h2><ol><li>In the left menu under <code>Advanced Setup</code>, go to <code>Wireless</code> › <code>Wireless Multibridge</code>.</li><li>In the <strong>2.4GHz</strong> box, choose <code>WISP</code> from the list. Do not choose <code>Repeater</code> — it changes the robot&#39;s address.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+r+'" alt="2.4GHz mode list in Wireless Multibridge" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Choose WISP for 2.4GHz ]</figcaption></figure><ol start="3"><li>The fields appear with the note <em>Wired WAN port will be disabled if Wireless WAN is ON.</em> Press the search button next to <code>SSID</code> (<code>AP Scan</code>).</li><li>In the <code>WiFi</code> window, pick the site Wi-Fi. Each name shows its channel and signal power. If the network is missing, press the refresh button at the top of the window.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+s+'" alt="AP Scan window" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Pick the Wi-Fi to join (network names hidden) ]</figcaption></figure><ol start="5"><li><code>SSID</code> and <code>Auth</code> fill in and a <code>Password</code> field appears. Enter the site Wi-Fi password and press <code>Apply</code> in the 2.4GHz box.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+c+'" alt="Wireless WAN fields" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Enter the password and apply ]</figcaption></figure><ol start="6"><li>The 2.4GHz box shows that wireless WAN is connected, with the signal strength, when it has joined.</li></ol><p>Leave <strong>5GHz</strong> at <code>Stop</code>. If the robot&#39;s own Wi-Fi is on 5GHz, wireless WAN there can drop the controller&#39;s connection while it switches.</p><h2 id="dynamic-ip" tabindex="-1">Step 3: Use a dynamic address <a class="header-anchor" href="#dynamic-ip" aria-label="Permalink to &quot;Step 3: Use a dynamic address {#dynamic-ip}&quot;">​</a></h2><p>Go to <code>Network</code> › <code>Internet Setup</code> (it is also in the shortcuts at the top left). If <code>Static</code> is selected, the router still holds the address from a previous site and the internet will not work. Choose <code>DHCP</code> and press <code>Apply</code>.</p><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+h+'" alt="Internet Setup screen" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Choose DHCP ]</figcaption></figure><h2 id="dns" tabindex="-1">Step 4: Set up the robot&#39;s DNS <a class="header-anchor" href="#dns" aria-label="Permalink to &quot;Step 4: Set up the robot&#39;s DNS {#dns}&quot;">​</a></h2><p>The robot PC uses a fixed address, so it does not get a name (DNS) server from the router. A robot with no DNS cannot find the remote check server even when the router is on the internet.</p><ol><li>Take control in the app.</li><li>Open <strong>Maintenance</strong> › <code>Robot Check</code> and scroll to <code>Remote check</code> at the bottom.</li><li>Press <code>Set up DNS</code>. <em>DNS is set up</em> means it worked.</li></ol><p>The robot points its DNS at the robot router (<code>192.168.0.1</code>). You only do this once — it keeps working when the site changes, because the router passes the lookups on to the DNS of the network it joined over wireless WAN.</p><h2 id="check" tabindex="-1">Step 5: Check <a class="header-anchor" href="#check" aria-label="Permalink to &quot;Step 5: Check {#check}&quot;">​</a></h2><p>Open <strong>Maintenance</strong> › <code>Robot Check</code> in the app and scroll to <code>Remote check</code> at the bottom. When the robot reaches the internet the warning about the internet goes away and the turn-on buttons become active. If it stays, check the steps above or ask support.</p>',27)])])}const x=t(d,[["render",l]]);export{f as __pageData,x as default};
